-- =====================================================================
-- Ejercicios con balón medicinal: lanzamientos y potencia (pedido de Manu).
-- Catálogo global, sin video todavía. No duplica nombres existentes.
-- =====================================================================
insert into public.exercises (name, category, muscle_groups, equipment, unilateral, instructions, coaching_cues)
select v.* from (values
-- Rotacionales (transferencia directa al swing)
('Lanzamiento rotacional de pie, de frente a la pared','potencia',array['Oblicuos','Cadera','Core']::text[],array['Balón medicinal']::text[],true,'De frente a la pared, a 1 metro, llevá el balón hacia la cadera de atrás y lanzalo rotando el cuerpo hasta quedar mirando la pared.','Empieza la cadera. Pie de atrás pivotea. Máxima velocidad en cada lanzamiento.'),
('Lanzamiento rotacional con paso','potencia',array['Oblicuos','Glúteos','Cadera']::text[],array['Balón medicinal']::text[],true,'De costado a la pared, dá un paso hacia la pared con el pie de adelante mientras cargás atrás, y lanzá rotando apenas apoya el pie.','Paso, apoyo y lanzamiento encadenados. Peso del pie de atrás al de adelante.'),
('Lanzamiento rotacional en posición de golf con paso','potencia',array['Oblicuos','Cadera','Core']::text[],array['Balón medicinal']::text[],true,'En postura de address, juntá los pies, dá un paso hacia el objetivo con el pie de adelante (como en el swing) y lanzá el balón contra la pared.','Paso antes de lanzar. La cadera abre primero. Mantené la inclinación del torso.'),
('Lanzamiento rotacional en contra del swing','potencia',array['Oblicuos','Cadera','Core']::text[],array['Balón medicinal']::text[],true,'Igual que el lanzamiento en posición de golf pero hacia el otro lado (como un jugador del otro perfil), para equilibrar el cuerpo.','Misma intención que del lado del swing. Menos carga si cuesta coordinar.'),
('Lanzamiento rotacional arrodillado','potencia',array['Oblicuos','Core','Columna torácica']::text[],array['Balón medicinal']::text[],true,'Arrodillado con las dos rodillas en el piso y de costado a la pared, rotá el torso y lanzá el balón sin mover la cadera.','Glúteos apretados. Rotación desde el tronco. Atrapá y repetí.'),
('Lanzamiento rotacional en media rodilla','potencia',array['Oblicuos','Core','Cadera']::text[],array['Balón medicinal']::text[],true,'Con una rodilla en el piso y la otra adelante, de costado a la pared, rotá y lanzá el balón con fuerza.','Torso erguido. Cadera estable. Rotación rápida.'),
('Lanzamiento rotacional sentado','potencia',array['Oblicuos','Core']::text[],array['Balón medicinal']::text[],true,'Sentado en el piso o en un cajón, de costado a la pared, rotá el torso y lanzá el balón.','Espalda larga. Solo rota el tronco. Velocidad máxima.'),
('Lanzamiento rotacional en una pierna','potencia',array['Oblicuos','Glúteos','Core']::text[],array['Balón medicinal']::text[],true,'Parado sobre la pierna de atrás, de costado a la pared, rotá y lanzá el balón manteniendo el equilibrio.','Rodilla apenas flexionada. Cadera estable. Lanzá sin perder el equilibrio.'),
('Lanzamiento rotacional con contramovimiento','potencia',array['Oblicuos','Cadera','Core']::text[],array['Balón medicinal']::text[],true,'De costado a la pared, hacé un giro rápido hacia atrás (carga) y sin pausa lanzá el balón rotando hacia la pared.','Carga rápida y cambio de dirección sin frenar. Aprovechá el estiramiento.'),
('Lanzamiento rotacional con pausa','potencia',array['Oblicuos','Cadera','Core']::text[],array['Balón medicinal']::text[],true,'De costado a la pared, cargá atrás, sostené 2 segundos y lanzá desde parado, sin rebote.','Pausa real en la carga. Todo el impulso sale de la cadera.'),
('Lanzamiento rotacional bajo (de cadera a la altura de la rodilla)','potencia',array['Oblicuos','Glúteos','Cadera']::text[],array['Balón medicinal']::text[],true,'De costado a la pared, llevá el balón por fuera de la rodilla de atrás y lanzá en diagonal hacia arriba, como un golpe de hacha invertido.','Bajá con la cadera, no con la espalda. Diagonal de abajo hacia arriba.'),
('Lanzamiento rotacional alto (diagonal hacia abajo)','potencia',array['Oblicuos','Dorsales','Core']::text[],array['Balón medicinal']::text[],true,'De costado a la pared, llevá el balón por encima del hombro de atrás y lanzalo en diagonal hacia abajo contra la pared o el piso.','Rotá y bajá a la vez. Pies firmes. Atrapá controlado.'),
('Slam rotacional de balón medicinal','potencia',array['Oblicuos','Dorsales','Core']::text[],array['Balón medicinal']::text[],true,'Con el balón arriba, rotá y lanzalo con fuerza contra el piso por fuera de un pie. Alterná o hacé todas de un lado.','Pivoteá el pie de atrás. Golpe con todo el cuerpo. Balón que no rebote.'),
('Pase rotacional con compañero','potencia',array['Oblicuos','Cadera','Core']::text[],array['Balón medicinal']::text[],true,'De costado a un compañero a 3–4 metros, recibí el balón, cargá atrás y devolvelo rotando con máxima velocidad.','Recibir y lanzar en un solo movimiento. Cadera inicia.'),
('Lanzamiento rotacional a distancia','potencia',array['Oblicuos','Cadera','Cuerpo completo']::text[],array['Balón medicinal']::text[],true,'En un espacio abierto, de costado a la dirección de lanzamiento, lanzá el balón lo más lejos posible rotando. Podés medir la distancia.','Máxima intención. Descanso completo entre lanzamientos.'),
-- Lanzamientos frontales y de pecho
('Pase de pecho contra la pared','potencia',array['Pectorales','Tríceps','Hombros']::text[],array['Balón medicinal']::text[],false,'De frente a la pared a 1–2 metros, lanzá el balón desde el pecho con fuerza y atrapalo al rebote.','Codos detrás del balón. Extensión rápida de brazos. Ritmo alto.'),
('Pase de pecho arrodillado','potencia',array['Pectorales','Tríceps','Core']::text[],array['Balón medicinal']::text[],false,'Arrodillado, lanzá el balón desde el pecho hacia adelante o contra la pared con máxima fuerza.','Glúteos apretados. Torso firme. Solo empujan los brazos.'),
('Pase de pecho con caída a flexión','potencia',array['Pectorales','Tríceps','Core']::text[],array['Balón medicinal','Colchoneta']::text[],false,'Arrodillado sobre colchoneta, lanzá el balón hacia adelante y dejate caer controlado a posición de flexión, amortiguando con las manos.','Cuerpo recto al caer. Codos suaves. Lanzá antes de caer.'),
('Pase de pecho a un brazo','potencia',array['Pectorales','Tríceps','Oblicuos']::text[],array['Balón medicinal']::text[],true,'En posición de estocada o de pie, empujá el balón con un brazo desde el pecho contra la pared, sumando rotación del torso.','Empuja la cadera y el tronco, después el brazo. Balón liviano.'),
('Lanzamiento de pecho con salto','potencia',array['Cuádriceps','Glúteos','Pectorales']::text[],array['Balón medicinal']::text[],false,'Con el balón en el pecho, bajá a media sentadilla y lanzalo hacia adelante y arriba mientras saltás.','Triple extensión. Balón y cuerpo salen juntos. Caída suave.'),
-- Por encima de la cabeza
('Lanzamiento por encima de la cabeza contra la pared','potencia',array['Dorsales','Tríceps','Core']::text[],array['Balón medicinal']::text[],false,'De frente a la pared, llevá el balón detrás de la cabeza y lanzalo con fuerza como un saque de lateral.','Costillas abajo. Lanzamiento con todo el cuerpo. Atrapá y repetí.'),
('Lanzamiento por encima de la cabeza arrodillado','potencia',array['Dorsales','Tríceps','Core']::text[],array['Balón medicinal']::text[],false,'Arrodillado frente a la pared, llevá el balón detrás de la cabeza y lanzalo con fuerza.','No arquees la espalda. Glúteos firmes. Brazos rápidos.'),
('Lanzamiento por encima de la cabeza con paso','potencia',array['Dorsales','Core','Cuerpo completo']::text[],array['Balón medicinal']::text[],false,'Con el balón detrás de la cabeza, dá un paso adelante y lanzalo lo más lejos posible.','Paso y lanzamiento encadenados. Extensión completa.'),
('Lanzamiento hacia adelante desde abajo (entre las piernas)','potencia',array['Glúteos','Isquiotibiales','Cuerpo completo']::text[],array['Balón medicinal']::text[],false,'Con el balón entre las piernas, hacé una bisagra de cadera y lanzalo hacia adelante y arriba extendiendo la cadera con fuerza.','Espalda neutra. La cadera empuja. Brazos largos.'),
('Lanzamiento vertical hacia arriba','potencia',array['Glúteos','Cuádriceps','Cuerpo completo']::text[],array['Balón medicinal']::text[],false,'Desde media sentadilla con el balón abajo, extendé todo el cuerpo y lanzalo lo más alto posible. Dejalo caer, no lo atrapes.','Triple extensión. Espacio libre arriba. Alejate al caer.'),
-- Slams y otros
('Slam de balón medicinal a un pie','potencia',array['Dorsales','Core','Glúteos']::text[],array['Balón medicinal']::text[],true,'Parado en una pierna, elevá el balón y golpealo contra el piso manteniendo el equilibrio.','Equilibrio primero. Core firme. Golpe fuerte.'),
('Slam de balón medicinal arrodillado','potencia',array['Dorsales','Core']::text[],array['Balón medicinal']::text[],false,'Arrodillado, elevá el balón y golpealo contra el piso adelante.','Sin arquear la espalda. Fuerza desde el tronco.'),
('Lanzamiento lateral desde cuclillas','potencia',array['Glúteos','Oblicuos','Cadera']::text[],array['Balón medicinal']::text[],true,'Desde media sentadilla de costado a la pared, extendé las piernas y rotá para lanzar el balón en diagonal hacia arriba.','Piernas y rotación al mismo tiempo. Pies firmes.'),
('Lanzamiento rotacional tras salto lateral','potencia',array['Glúteos','Oblicuos','Cadera']::text[],array['Balón medicinal']::text[],true,'Con el balón en el pecho, hacé un salto lateral alejándote de la pared, caé en la pierna de atrás y lanzá rotando apenas apoyás.','Caída estable. Cargá en la cadera de atrás. Lanzamiento inmediato.'),
('Abdominal con lanzamiento de balón','core',array['Abdominales','Core']::text[],array['Balón medicinal']::text[],false,'Acostado con rodillas flexionadas frente a la pared o un compañero, subí haciendo un abdominal y lanzá el balón desde el pecho o por encima de la cabeza.','Subí con el abdomen. Lanzamiento al final de la subida. Bajada controlada.'),
('Abdominal rotacional con lanzamiento','core',array['Oblicuos','Abdominales']::text[],array['Balón medicinal']::text[],true,'Sentado de costado a la pared, recibí el balón, rotá hacia atrás y lanzalo rotando hacia la pared.','Espalda larga. Rotación rápida. Pies apoyados.'),
('Rotación rusa con lanzamiento','core',array['Oblicuos','Core']::text[],array['Balón medicinal']::text[],false,'Sentado con el tronco inclinado y pies elevados o apoyados, lanzá el balón a un compañero o a la pared rotando de un lado al otro.','Rotar el tronco. Core firme. Ritmo constante.'),
('Desaceleración rotacional con balón','estabilidad',array['Oblicuos','Core','Cadera']::text[],array['Balón medicinal']::text[],true,'Un compañero te lanza el balón de costado: recibilo y frená la rotación hacia atrás, quedando estable 2 segundos antes de devolverlo.','Frená con la cadera y el tronco. Pies firmes. Sin perder la postura.'),
('Lanzamiento rotacional reactivo','potencia',array['Oblicuos','Cadera','Core']::text[],array['Balón medicinal']::text[],true,'De costado a la pared a 1 metro, lanzá y atrapá el balón seguido, sin pausa, lo más rápido posible durante el tiempo indicado.','Contacto corto. Cadera activa. Ritmo máximo sin perder la técnica.')
) as v(name, category, muscle_groups, equipment, unilateral, instructions, coaching_cues)
where not exists (select 1 from public.exercises e where e.org_id is null and e.name = v.name);
